package org.kanger;
import java.nio.file.*;
import java.util.*;
import org.kanger.ContextProductionCapture.Atom;
import org.kanger.ContextProductionCapture.Clause;
import org.kanger.ContextProductionNativeBinding.Entry;
import org.kanger.ContextProductionNativeBinding.Result;

/** Mixed diagonal/independent result clauses retain one whole assertion Source. */
public final class ContextConjunctiveOuterExistentialScopeRunner {
    static int checks,ids;
    static void require(boolean value,String why){++checks;if(!value)throw new AssertionError(why);}
    static Result bind(String text,int primary)throws Exception{User u=new User();Mind m=new Mind(u);u.setCurrentMind(m);require(m.compile(text,null,false),"native conjunction parses");ContextProductionInventory inv=ContextProductionInventory.inspect(m,new UUID(0,++ids),1,false,Collections.emptyList(),1000);require(inv.primary.size()==primary,"exact whole primary assertion count");Result r=ContextProductionNativeBinding.bind(m,inv,64000000,500000);require(r.bound,"complete whole declaration binding: "+r.reason);return r;}
    static Map<String,Clause> clauses(Result r,boolean leading,boolean negative){Map<String,Clause> result=new HashMap<>();for(Entry e:r.snapshot.primary){require(e.kind==ContextProductionNativeBinding.Kind.CLAUSES&&e.witnesses()==0,"universal clause group, no witness");for(Clause c:e.clauses){require(c.variables.size()==3&&c.literals.size()==2,"all input slots retained in each branch");Atom rel=c.literals.stream().filter(a->a.predicate.equals("rel")).findFirst().get(),out=c.literals.stream().filter(a->a.predicate.equals("out")).findFirst().get();int u=leading?2:0,v=leading?1:2;require(rel.positive==negative&&out.positive!=negative&&rel.arguments.size()==3&&out.arguments.size()==2,"exact ternary input/binary output signs");require(rel.arguments.stream().allMatch(a->a.variable>=0)&&rel.arguments.stream().map(a->a.variable).distinct().count()==3,"three distinct input variables");boolean diagonal=out.arguments.get(0).variable==out.arguments.get(1).variable;require(out.arguments.get(0).variable==rel.arguments.get(diagonal?u:v).variable&&out.arguments.get(1).variable==rel.arguments.get(u).variable,"exact diagonal or independent result mapping");require(result.put(diagonal?"diagonal":"independent",c)==null,"each branch retained once");}}require(result.keySet().equals(new HashSet<>(Arrays.asList("diagonal","independent"))),"both required result clauses");return result;}
    static Map<String,Clause> capture(String text,boolean leading,boolean negative)throws Exception{Result r=bind(text,1);require(r.snapshot.primary.size()==1&&r.snapshot.primary.get(0).clauses.size()==2,"two clauses under exactly one whole Source");return clauses(r,leading,negative);}
    static void equivalent(Map<String,Clause> a,Map<String,Clause> b){for(String k:a.keySet())require(a.get(k).equivalent(b.get(k)),"corresponding branch alpha-equivalent: "+k);}
    static void one(boolean leading,boolean negative)throws Exception{String s=negative?"~":"",args=leading?"x,v,u":"u,x,v",alpha=leading?"z,w,p":"p,z,w",prefix="!@u @v ($x "+s+"rel("+args+"))->",head="("+s+"out(u,u)&&"+s+"out(v,u));";Map<String,Clause> whole=capture(prefix+head,leading,negative);equivalent(whole,capture("!@u @v @x "+s+"rel("+args+")->"+head,leading,negative));equivalent(whole,capture("!@p @w ($z "+s+"rel("+alpha+"))->("+s+"out(p,p)&&"+s+"out(w,p));",leading,negative));Result split=bind(prefix+s+"out(u,u); "+prefix+s+"out(v,u);",2);require(split.snapshot.primary.stream().allMatch(e->e.clauses.size()==1)&&!split.snapshot.primary.get(0).source.equals(split.snapshot.primary.get(1).source),"separate assertions have two Sources, never replace a whole compound Source");equivalent(whole,clauses(split,leading,negative));}
    public static void main(String[] args){try{System.setProperty("user.home",Files.createTempDirectory("conjunctive-outer-scope-").toString());for(boolean l:new boolean[]{false,true})for(boolean n:new boolean[]{false,true})one(l,n);System.out.println("CONTEXT_CONJUNCTIVE_OUTER_EXISTENTIAL_SCOPE_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
